n = len(HE)
for i, c in enumerate(HE):
    en = EN[c['slug']]
    body = c['body'] + '\n' + gal_html(en.get('gallery', []))
    if en.get('extra'):
        extra = en['extra'].replace('../assets','../../assets')
        extra = extra.replace('Event reel · June 16, 2026', CAP_HE['Event reel · June 16, 2026'])
        body += '\n' + extra
    mode = ' case__img--' + en['mode'] if en.get('mode') else ''
    if en.get('heroVideo'):
        hv = en['heroVideo'].replace('../assets','../../assets'); hp = en['heroPoster'].replace('../assets','../../assets')
        hero = (f'<div class="case__img case__img--video">'
                f'<video src="{hv}" poster="{hp}" autoplay loop muted playsinline preload="metadata"></video></div>')
    elif en.get('local'):
        hero = f'<div class="case__img{mode}"><img src="{en["local"].replace("../assets","../../assets")}" alt="{html.escape(c["title"])}"></div>'
    elif en.get('hero'):
        hero = f'<div class="case__img{mode}"><img src="{WIX}{en["hero"]}" alt="{html.escape(c["title"])}"></div>'
    else:
        hero = '<div class="case__img case__img--empty mono"><span>חומרים חזותיים — בקרוב</span></div>'
    page = TPL.format(slug=c['slug'], title=html.escape(c['title']), venue=c['venue'], year=c['year'], cat=c['cat'],
                      heroblock=hero, body=body,
                      prev=HE[i-1]['slug']+'.html', next=HE[(i+1) % n]['slug']+'.html')
    open(os.path.join(OUT, c['slug']+'.html'), 'w', encoding='utf-8').write(page)
    print(c['slug'], 'he ok')
